class Solution {
  private static final long MOD = 1_000_000_007L;

  private static long pow(long b, long e) {
    long r = 1;
    for (b %= MOD; e > 0; e >>= 1) {
      if ((e & 1) == 1) r = r * b % MOD;
      b = b * b % MOD;
    }
    return r;
  }

  public int countGoodArrays(int n, int m, int k) {
    long num = 1, den = 1;
    for (int i = 1; i <= k; i++) {
      num = num * (n - i) % MOD;
      den = den * i % MOD;
    }
    long comb = num * pow(den, MOD - 2) % MOD;
    return (int) (m % MOD * comb % MOD * pow(m - 1, n - 1 - k) % MOD);
  }
}
